using System.IO;
using UnityEditor;
using UnityEngine;
public static class FixRoleSprites {
  public static string Run() {
    int n = 0;
    string[] folders = { "Assets/Bundle/Role", "Assets/Bundle/Item/icon" };
    foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", folders)) {
      string p = AssetDatabase.GUIDToAssetPath(guid);
      var imp = AssetImporter.GetAtPath(p) as TextureImporter;
      if (imp == null) continue;
      bool dirty = false;
      if (imp.textureType != TextureImporterType.Sprite) { imp.textureType = TextureImporterType.Sprite; dirty = true; }
      if (imp.spriteImportMode != SpriteImportMode.Single) { imp.spriteImportMode = SpriteImportMode.Single; dirty = true; }
      if (imp.mipmapEnabled) { imp.mipmapEnabled = false; dirty = true; }
      if (!imp.alphaIsTransparency) { imp.alphaIsTransparency = true; dirty = true; }
      if (p.Replace('\\','/').Contains("/battle/")) {
        var s = new TextureImporterSettings();
        imp.ReadTextureSettings(s);
        var pivot = new Vector2(0.5f, 0.12f);
        if (s.spriteAlignment != (int)SpriteAlignment.Custom || s.spritePivot != pivot) {
          s.spriteAlignment = (int)SpriteAlignment.Custom;
          s.spritePivot = pivot;
          imp.SetTextureSettings(s);
          dirty = true;
        }
      }
      if (dirty) { imp.SaveAndReimport(); n++; }
    }
    return "sprites " + n;
  }
}
